using namespace chmt;
void require(bool ok,const char* message){if(!ok){std::cerr<<message<<'\n';std::exit(2);}}
struct Case {Real b[Ns]{},y[Ns]{},j[Ns]{};PhysicsConfig p;};
Real norm(const Real* f){Real n=0;for(int i=0;i<Ns;++i)n=std::max(n,std::abs(f[i]));return n;}
void originalFlux(Case& c,Real J){Real R=0,S=0;for(int i=0;i<Ns;++i)R+=c.p.species[i].R*c.y[i];Real rho=101325/(R*300);for(int i=0;i<Ns;++i)S+=rho*c.p.gasDiffusivity[i]/.01*(c.y[i]-c.b[i]);for(int i=0;i<Ns;++i)c.j[i]=J*c.y[i]+rho*c.p.gasDiffusivity[i]/.01*(c.y[i]-c.b[i])-c.y[i]*S;}
void output(const char* label,const Real* v){std::cout<<label;for(int i=0;i<Ns;++i)std::cout<<' '<<v[i];std::cout<<'\n';}
int main(int argc,char**argv){std::cout<<std::setprecision(17)<<std::unitbuf;require(argc==2,"mode missing");const std::string mode=argv[1];feenableexcept(FE_OVERFLOW|FE_INVALID|FE_DIVBYZERO);const int mask=fegetexcept();
if(mode=="boundary"){
 std::mt19937_64 rng(1738291);std::uniform_real_distribution<Real> u(0,1);int bad=0,total=0;
 for(int kind=0;kind<6;++kind)for(int k=0;k<200;++k){Case c;Real sb=0,sy=0;for(int s=0;s<Ns;++s){c.b[s]=.01+u(rng);c.y[s]=.01+u(rng);if(kind<2)c.y[s]=(s==k%Ns)?1:0;else if(kind<4&&s%2==0)c.y[s]=0;else if(kind>=4&&s%2==0)c.b[s]=0;sb+=c.b[s];sy+=c.y[s];c.p.species[s].R=10+1000*u(rng);c.p.gasDiffusivity[s]=1e-6+.01*u(rng);}for(int s=0;s<Ns;++s){c.b[s]/=sb;c.y[s]/=sy;}originalFlux(c,(kind%2?-1:1)*(.01+.1*u(rng)));Real f[Ns]{},out[Ns]{};for(auto& v:out)v=123;Real tolerance=1e-12;for(int s=0;s<Ns;++s)tolerance+=c.p.tolerances.relativeMass*std::abs(c.j[s]);require(compositionResidual(c.y,c.b,c.j,101325,300,.01,c.p,f,nullptr)&&norm(f)<=tolerance,"manufactured reference is not an original-equation root");bool ok=interfaceComposition(c.j,c.b,101325,300,.01,c.p,1e-12,out);bool good=ok&&compositionResidual(out,c.b,c.j,101325,300,.01,c.p,f,nullptr);Real sum=0;for(auto y:out){sum+=y;good=good&&chmt::finite(y)&&y>=0&&y<=1;}good=good&&std::abs(sum-1)<1e-13&&norm(f)<=tolerance;++total;if(!good){++bad;if(bad<=2){std::cout<<"BAD kind="<<kind<<" case="<<k<<" ok="<<ok<<" residual="<<norm(f)<<" tolerance="<<tolerance<<'\n';output("bulk",c.b);output("known_root",c.y);output("Js",c.j);output("out",out);}}}
 std::cout<<"BOUNDARY ns="<<Ns<<" cases="<<total<<" bad="<<bad<<'\n';require(bad==0,"legal zero/pure-species roots were lost");
}else if(mode=="endpoint"){
 if(Ns!=3)return 3;
 for(Real root:{Real(.25),Real(.5),Real(.7)}){composition_detail::Poly p;p.degree=3;p.c[0]=0;p.c[1]=2*root/3;p.c[2]=4*root/3-(root+2)/3;p.c[3]=root-1;Real points[composition_detail::ScalarCandidateCapacity]{};composition_detail::Info info;int n=composition_detail::roots(p,info,points);bool found=false;std::cout<<"ENDPOINT expected="<<root<<" count="<<n;for(int i=0;i<n;++i){std::cout<<' '<<points[i];found=found||std::abs(points[i]-root)<2e-14;}std::cout<<'\n';require(found,"left-endpoint factor hid an interior root");}
}else if(mode=="near"){
 std::mt19937_64 rng(912831);std::uniform_real_distribution<Real> u(0,1);int total=0,bad=0,converged=0;
 for(Real delta:{Real(1e-10),Real(1e-12),Real(1e-14),Real(1e-15),Real(1e-16)})for(int k=0;k<120;++k){Case c;Real sb=0,sy=0;for(int s=0;s<Ns;++s){c.b[s]=.1+u(rng);sb+=c.b[s];c.p.species[s].R=100+1000*u(rng);c.p.gasDiffusivity[s]=.001+.01*u(rng);}for(int s=0;s<Ns;++s){c.b[s]/=sb;c.y[s]=c.b[s]*(1+delta*(u(rng)-.5));sy+=c.y[s];}for(int s=0;s<Ns;++s)c.y[s]/=sy;originalFlux(c,.1);c.p.tolerances.relativeMass=0;Real knownF[Ns]{},out[Ns]{},actualF[Ns]{};require(compositionResidual(c.y,c.b,c.j,101325,300,.01,c.p,knownF,nullptr),"near reference invalid");const Real tolerance=std::max(1e-20,norm(knownF)*8);composition_detail::Info info;bool ok=composition_detail::scalarSolve(c.j,c.b,101325,300,.01,c.p,tolerance,out,&info);bool good=ok&&compositionResidual(out,c.b,c.j,101325,300,.01,c.p,actualF,nullptr);Real sum=0;for(auto y:out){sum+=y;good=good&&chmt::finite(y)&&y>=0&&y<=1;}good=good&&std::abs(sum-1)<1e-13&&chmt::finite(norm(actualF));if(info.state==composition_detail::SolveState::Converged){++converged;good=good&&norm(actualF)<=tolerance;}else if(ok)good=good&&info.state==composition_detail::SolveState::AdmissibleApproximation&&info.actualResidual==norm(actualF);++total;if(!good){++bad;if(bad<=3)std::cout<<"NEAR_BAD delta="<<delta<<" case="<<k<<" ok="<<ok<<" ref="<<norm(knownF)<<" actual="<<norm(actualF)<<" tolerance="<<tolerance<<" state="<<int(info.state)<<'\n';}}
 std::cout<<"NEAR ns="<<Ns<<" cases="<<total<<" bad="<<bad<<" converged="<<converged<<'\n';require(bad==0,"near-proportional Collatz path lost legal finite state or mislabeled residual");
}else if(mode=="arithmetic"){
 const Real maximum=std::numeric_limits<Real>::max();const Real pairs[][2]={{1.326606445035236e308,1.3551065891396052},{1.2349171062158004e308,1.4557196801419729},{1.2439684289169992e308,1.4451276198604093},{1.1468980131490644e308,1.5674394011079924},{1.1169978285288319e308,1.6093971617026415},{maximum/2,2},{maximum,1},{maximum,0},{-maximum/2,2},{1e-200,1e-200}};
 const long double roundingOverflow=static_cast<long double>(maximum)+std::ldexp(1.L,970);
 const Real addends[][2]={{std::nextafter(maximum,Real(0)),std::ldexp(Real(1.5),971)},{0x1.ea667e2e0c0d1p+1020,0x1.c2b3303a3e7e5p+1023},{maximum,-maximum},{maximum/2,maximum/2}};
 for(const auto& pair:addends){const long double exact=static_cast<long double>(pair[0])+pair[1];const bool expected=std::abs(exact)<roundingOverflow;const Real reference=expected?static_cast<Real>(exact):0;Real actual=123;std::cout<<"SUM "<<pair[0]<<' '<<pair[1]<<" expected="<<expected<<'\n';std::feclearexcept(FE_OVERFLOW|FE_INVALID|FE_DIVBYZERO);bool ok=composition_detail::sumFinite(pair[0],pair[1],actual);require(ok==expected,"sum threshold classification incorrect");if(ok)require(actual==reference,"sum changed representable arithmetic");require(!std::fetestexcept(FE_OVERFLOW|FE_INVALID|FE_DIVBYZERO),"sum guard executed trapping arithmetic");}
 for(const auto& pair:pairs){const long double exact=static_cast<long double>(pair[0])*pair[1];const bool expected=std::abs(exact)<roundingOverflow;const Real reference=expected?static_cast<Real>(exact):0;Real actual=123;std::cout<<"PRODUCT "<<pair[0]<<' '<<pair[1]<<" expected="<<expected<<'\n';std::feclearexcept(FE_OVERFLOW|FE_INVALID|FE_DIVBYZERO);bool ok=composition_detail::productFinite(pair[0],pair[1],actual);require(ok==expected,"product threshold classification incorrect");if(ok)require(actual==reference,"product changed representable arithmetic");require(!std::fetestexcept(FE_OVERFLOW|FE_INVALID|FE_DIVBYZERO),"product guard executed trapping arithmetic");}
 const Real divisors[][2]={{maximum,1},{maximum,.5},{maximum/2,.5},{maximum/2,1},{1,3},{1e-300,1e300},{0,1},{1,0},{0,0},{-maximum,.5}};
 for(const auto& pair:divisors){const bool defined=pair[1]!=0;const long double exact=defined?static_cast<long double>(pair[0])/pair[1]:0;const bool expected=defined&&std::abs(exact)<roundingOverflow;const Real reference=expected?static_cast<Real>(exact):0;Real actual=123;std::feclearexcept(FE_OVERFLOW|FE_INVALID|FE_DIVBYZERO);bool ok=composition_detail::quotientFinite(pair[0],pair[1],actual);require(ok==expected,"quotient threshold classification incorrect");if(ok)require(actual==reference,"quotient changed representable arithmetic");require(!std::fetestexcept(FE_OVERFLOW|FE_INVALID|FE_DIVBYZERO),"quotient guard executed trapping arithmetic");}
}else return 4;
require(fegetexcept()==mask,"operator changed trap mask");return 0;}
